{"file_path":"src/block.js","content":"/** Block parsing: fences, headings, link definitions, nested lists, and paragraphs. */

import { escapeText } from './html.js'
import { normalizeLabel, renderInline } from './inline.js'

const FENCE = /^(`{3,})([^`]*)$/
const HEADING = /^(#{1,6}) (.*)$/
const ITEM = /^( *)- (.*)$/

/** A line whose trimmed text records a link definition. */
export const DEFINITION = /^\[([^\]]*)\]:\s+(\S.*)$/u

/** One refusal of a document line, carrying the 1-based line it was read at. */
export class BlockError extends Error {
  /**
   * @param {number} line - the 1-based input line.
   * @param {string} message - the message the specification words, without the position.
   */
  constructor(line, message) {
    super(message)
    this.name = 'BlockError'
    this.line = line
  }
}

/**
 * Every input line, with the empty tail a trailing newline leaves dropped.
 * @param {string} text - the whole input.
 * @returns {string[]} the lines.
 */
export function splitLines(text) {
  const split = text.split('\n')
  if (split.length > 0 && split[split.length - 1] === '') split.pop()
  return split
}

/**
 * The blocks of one document.
 * @param {string[]} lines - the document's lines.
 * @param {Map<string, {url: string, source: string}>} [definitions] - the definitions in force, which the document's own join.
 * @returns {object[]} the blocks in document order.
 * @throws {BlockError} on an unterminated fence or a label defined twice.
 */
export function parse(lines, definitions = new Map()) {
  const out = []
  let paragraph = []
  let items
  let open = []
  const flush = () => {
    if (paragraph.length > 0) {
      out.push({ kind: 'paragraph', lines: paragraph })
      paragraph = []
    }
    if (items !== undefined) {
      out.push({ kind: 'list', items })
      items = undefined
      open = []
    }
  }
  for (let index = 0; index < lines.length; index += 1) {
    const raw = lines[index]
    const line = index + 1
    const fence = FENCE.exec(raw)
    if (fence !== null) {
      flush()
      const content = []
      let close = -1
      for (let scan = index + 1; scan < lines.length; scan += 1) {
        const candidate = lines[scan].trim()
        if (/^`{3,}$/u.test(candidate) && candidate.length >= fence[1].length) {
          close = scan
          break
        }
        content.push(lines[scan])
      }
      if (close === -1) throw new BlockError(line, 'unterminated code fence')
      out.push({ kind: 'fence', info: fence[2].trim().split(/\s+/u)[0], content })
      index = close
      continue
    }
    if (raw.trim() === '') {
      flush()
      continue
    }
    const definition = DEFINITION.exec(raw.trim())
    if (definition !== null) {
      flush()
      const label = normalizeLabel(definition[1])
      if (definitions.has(label)) throw new BlockError(line, `label ${label} is defined twice`)
      definitions.set(label, { url: definition[2], source: 'document' })
      continue
    }
    const heading = HEADING.exec(raw)
    if (heading !== null) {
      flush()
      out.push({ kind: 'heading', level: heading[1].length, text: heading[2].trim() })
      continue
    }
    const item = ITEM.exec(raw)
    if (item !== null && paragraph.length === 0) {
      if (items === undefined) {
        items = []
        open = [items]
      }
      const level = Math.min(Math.floor(item[1].length / 2), open.length - 1)
      const node = { text: item[2].trim(), children: [] }
      open[level].push(node)
      open = open.slice(0, level + 1)
      open.push(node.children)
      continue
    }
    if (items !== undefined) flush()
    paragraph.push(raw.trim())
  }
  flush()
  return out
}

/** One list's lines, the nested lists indented by nothing but their own elements. */
function renderItems(items, definitions) {
  const lines = ['<ul>']
  for (const item of items) {
    const text = renderInline(item.text, definitions)
    if (item.children.length === 0) {
      lines.push(`<li>${text}</li>`)
      continue
    }
    lines.push(`<li>${text}`, ...renderItems(item.children, definitions), '</li>')
  }
  lines.push('</ul>')
  return lines
}

/**
 * Render parsed blocks to HTML.
 * @param {readonly object[]} parsed - the document's blocks.
 * @param {Map<string, {url: string, source: string}>} [definitions] - the link definitions in force.
 * @returns {string} the HTML, with a trailing newline unless the document holds no block.
 */
export function render(parsed, definitions = new Map()) {
  const rendered = parsed.map((block) => {
    if (block.kind === 'heading') {
      return `<h${block.level}>${renderInline(block.text, definitions)}</h${block.level}>`
    }
    if (block.kind === 'paragraph') {
      return `<p>${block.lines.map(text => renderInline(text, definitions)).join('\n')}</p>`
    }
    if (block.kind === 'list') return renderItems(block.items, definitions).join('\n')
    const open = block.info === '' ? '<pre><code>' : `<pre><code class="language-${escapeText(block.info)}">`
    return `${open}${block.content.map(text => `${escapeText(text)}\n`).join('')}</code></pre>`
  })
