/** The command: `html`, `outline`, and `defs`, each over the document on standard input. */

import { readFileSync } from 'node:fs'
import { BlockError, DEFINITION, headings, parse, render, splitLines } from './block.js'
import { normalizeLabel } from './inline.js'

const USAGE = 'usage: cli.js html|outline|defs [<definitions>]'

/** Report one failure the way the specification words it, and stop. */
function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

/**
 * Every definition one definitions file holds, in the order it wrote them.
 * @param {string} path - the file as the argument list named it.
 * @returns {Map<string, {url: string, source: string}>} the definitions.
 */
function readDefinitions(path) {
  let text
  try {
    text = readFileSync(path, 'utf8')
  } catch {
    fail(`cannot read definitions ${path}`)
  }
  const definitions = new Map()
  const lines = splitLines(text)
  for (let index = 0; index < lines.length; index += 1) {
    const line = lines[index].trim()
    const number = index + 1
    if (line === '' || line.startsWith('#')) continue
    const definition = DEFINITION.exec(line)
    if (definition === null) fail(`${path}: line ${number}: expected [label]: <url>`)
    const label = normalizeLabel(definition[1])
    if (definitions.has(label)) fail(`${path}: line ${number}: label ${label} is defined twice`)
    definitions.set(label, { url: definition[2], source: 'file' })
  }
  return definitions
}

const argv = process.argv.slice(2)
const mode = argv[0]
if (!['html', 'outline', 'defs'].includes(mode) || argv.length > 2) fail(USAGE)

const definitions = argv.length === 2 ? readDefinitions(argv[1]) : new Map()

let parsed
try {
  parsed = parse(splitLines(readFileSync(0, 'utf8')), definitions)
} catch (error) {
  if (!(error instanceof BlockError)) throw error
  fail(`line ${error.line}: ${error.message}`)
}

if (mode === 'html') {
  process.stdout.write(render(parsed, definitions))
} else if (mode === 'outline') {
  process.stdout.write(headings(parsed).map(one => `${one.level} ${one.text}\n`).join(''))
} else {
  const labels = [...definitions.keys()].sort((one, other) => (one < other ? -1 : one > other ? 1 : 0))
  const listed = labels.map(label => `${label} ${definitions.get(label).url} ${definitions.get(label).source}\n`).join('')
  process.stdout.write(`${listed}total ${labels.length}\n`)
}
"}

